                if given(a) and given(a) == given(b):
                    add(a, b, 0)
    for members_ in buckets(lambda n: nkey[n]).values():
        for i, a in enumerate(members_):
            for b in members_[i + 1:]:
                if dob[a] is not None and dob[a] == dob[b]:
                    add(a, b, 1)
                if pkey[a] and pkey[a] == pkey[b]:
                    add(a, b, 2)

    group_of = {n: n for n in nums}
    group_members = {n: [n] for n in nums}
    group_rules: dict[int, set[int]] = {n: set() for n in nums}
    refused = []
    for (a, b), rule in sorted(pairs.items(), key=lambda kv: (kv[1], kv[0][0], kv[0][1])):
        ga, gb = group_of[a], group_of[b]
        if ga == gb:
            continue
        if any(kept_apart(x, y) for x in group_members[ga] for y in group_members[gb]):
            refused.append((a, b, RULES[rule]))
            continue
        # merge gb into ga
        group_members[ga].extend(group_members[gb])
        for x in group_members[gb]:
            group_of[x] = ga
        group_rules[ga] |= group_rules[gb] | {rule}
        del group_members[gb], group_rules[gb]

    groups = []
    for g, mem in group_members.items():
        if len(mem) < 2:
            continue
        groups.append(_merge_group(members, mem, sorted(group_rules[g]), joined, when))
    groups.sort(key=lambda g: g["survivor"])
    return groups, refused


def _merge_group(members, mem, rules, joined, when):
    survivor = min(mem, key=lambda n: (joined[n], n))
    prec = sorted(sorted(mem), key=lambda n: when[n], reverse=True)
    old = members[survivor]
    new = dict(old)
    source = {}

    def first_nonempty(field):
        for n in prec:
            if members[n][field] != "":
                return n
        return None

    if old["name"] == "":
        n = first_nonempty("name")
        if n is not None:
            new["name"] = members[n]["name"]
            source["name"] = n
    for f in ("email", "phone", "dob"):
        n = first_nonempty(f)
        new[f] = members[n][f] if n is not None else ""
        source[f] = n
    best, best_n = None, None
    for n in prec:
        if members[n]["expires"] != "":
            d = dates.parse_day(members[n]["expires"])
            if best is None or d > best:
                best, best_n = d, n
    new["expires"] = members[best_n]["expires"] if best_n is not None else ""
    source["expires"] = best_n
    n = first_nonempty("marketing")
    new["marketing"] = members[n]["marketing"] if n is not None else ""
    tags = set()
    for m in mem:
        tags.update(tag_list(members[m]))
    new["tags"] = sorted(tags)
    return {"survivor": survivor, "merged": sorted(m for m in mem if m != survivor), "rules": [RULES[r] for r in rules],
            "old": old, "new": new, "source": source}


def finish_changes(group: dict, stamp: str) -> None:
    old, new = group["old"], group["new"]
    new["updated"] = stamp
    changes = {f: [old[f], new[f]] for f in FIELD_ORDER if old[f] != new[f]}
    group["changes"] = changes
    group["from"] = {f: ids.fmt(group["source"][f]) for f in FROM_FIELDS
                     if f in changes and group["source"].get(f) is not None}


def render(groups: list[dict], refused: list) -> list[str]:
    lines = []
    for g in groups:
        lines.append(f"merge {ids.fmt(g['survivor'])} <- {', '.join(ids.fmt(m) for m in g['merged'])} "
                     f"({', '.join(g['rules'])})")
        for f, (b, a) in g["changes"].items():
            lines.append(f"  {f}: {json.dumps(b, ensure_ascii=False)} -> {json.dumps(a, ensure_ascii=False)}")
    for a, b, rule in refused:
        lines.append(f"kept apart {ids.fmt(a)} {ids.fmt(b)} ({rule})")
    lines.append(f"{len(groups)} groups, {sum(len(g['merged']) for g in groups)} members merged, "
                 f"{len(refused)} pairs kept apart")
    return lines

