def cmd_merge(ctx, a):
    reg = ctx.members
    alias_map = ctx.aliases
    settings = merge.load_settings(ctx.data / "settings.json")
    keep_rows = merge.load_keep_apart(ctx.data / "keep_apart.csv")
    groups, refused = merge.plan(reg, alias_map, settings, keep_rows)
    for g in groups:
        merge.finish_changes(g, ctx.stamp)
    lines = merge.render(groups, refused)
    if not a.apply:
        return lines + ["dry run: nothing written"]
    if not groups:
        return lines
    survivor_of = {}
    for g in groups:
        for m in g["merged"]:
            survivor_of[m] = g["survivor"]
    register = {n: r for n, r in reg.items() if n not in survivor_of}
    for g in groups:
        register[g["survivor"]] = g["new"]
    new_aliases = {k: survivor_of.get(v, v) for k, v in alias_map.items()}
    new_aliases.update(survivor_of)
    rows = []
    for r in ctx.payments:
        n = ids.number(r["member"])
        if n is not None and aliases.resolve(alias_map, n) in survivor_of:
            r = {**r, "member": ids.fmt(survivor_of[aliases.resolve(alias_map, n)])}
        rows.append(r)
    seq = audit.next_seq(ctx.entries)
    entries = []
    for i, g in enumerate(groups):
        entries.append({"seq": seq + i, "at": ctx.stamp, "op": "merge", "by": ctx.by, "member": ids.fmt(g["survivor"]),
                        "merged": [ids.fmt(m) for m in g["merged"]], "rules": g["rules"],
                        "changes": g["changes"], "from": g["from"]})
    ctx.commit(register=register, alias_map=new_aliases, payment_rows=rows, new_entries=entries)
    return lines


